<script setup>
import { inject, onMounted, ref, computed } from 'vue'
import { authorizedRequest } from './auth.js'
import RefreshIcon from './RefreshIcon.vue'
import { usePagination } from './pagination.js'
const can = inject('canPermission', () => false)
const services = ref([]), callers = ref([]), grants = ref([]), usage = ref([]), datasets = ref([]), users = ref([]), error = ref(''), message = ref(''), token = ref('')
const form = ref({ name: '', datasetId: null, fields: [], limit: 100 }), caller = ref({ name: '', userId: null, limitPerMinute: 60 }), grant = ref({ service: null, caller: null })
const serviceDialog = ref(false), callerDialog = ref(false), grantDialog = ref(false)
const serviceSearch = ref(''), serviceFilter = ref(''), callerSearch = ref(''), callerFilter = ref(''), grantSearch = ref(''), grantFilter = ref(''), usageSearch = ref(''), usageFilter = ref('')
function includes(value, query) { return String(value ?? '').toLocaleLowerCase().includes(query) }
function filterRows(rows, query, fields) { return rows.value.filter(row => !query || fields.some(field => includes(row[field], query))) }
const filteredServices = computed(() => filterRows(services, serviceFilter.value.toLocaleLowerCase(), ['name', 'state']))
const filteredCallers = computed(() => filterRows(callers, callerFilter.value.toLocaleLowerCase(), ['name', 'userId', 'enabled']))
const filteredGrants = computed(() => filterRows(grants, grantFilter.value.toLocaleLowerCase(), ['serviceId', 'callerId']))
const filteredUsage = computed(() => filterRows(usage, usageFilter.value.toLocaleLowerCase(), ['serviceId', 'callerId']))
const { page: servicePage, visible: visibleServices } = usePagination(filteredServices)
const { page: callerPage, visible: visibleCallers } = usePagination(filteredCallers)
const { page: grantPage, visible: visibleGrants } = usePagination(filteredGrants)
const { page: usagePage, visible: visibleUsage } = usePagination(filteredUsage)
const dataset = computed(() => datasets.value.find(d => d.id === form.value.datasetId))
function applyServiceQuery() { serviceFilter.value = serviceSearch.value.trim(); servicePage.value = 1 }
function applyCallerQuery() { callerFilter.value = callerSearch.value.trim(); callerPage.value = 1 }
function applyGrantQuery() { grantFilter.value = grantSearch.value.trim(); grantPage.value = 1 }
function applyUsageQuery() { usageFilter.value = usageSearch.value.trim(); usagePage.value = 1 }
async function get(url) { const r = await fetch(url, { credentials: 'same-origin' }); if (!r.ok) throw new Error(r.status === 403 ? '当前账号没有相应管理或数据集权限' : '读取失败'); return r.json() }
async function post(url, body) { const r = await authorizedRequest(url, { method: 'POST', ...(body === undefined ? {} : { headers: { 'Content-Type':'application/json' }, body: JSON.stringify(body) }) }); if (!r.ok) throw new Error(r.status === 403 ? '当前账号没有相应权限' : '操作失败，请检查状态和配置'); return r.status === 204 ? null : r.json() }
async function load() { try { [services.value, callers.value, grants.value, usage.value, datasets.value] = await Promise.all([can('service.service.read') ? get('/api/services') : Promise.resolve([]), can('service.caller.read') ? get('/api/service-callers') : Promise.resolve([]), can('service.caller.read') ? get('/api/service-grants') : Promise.resolve([]), can('service.service.read') ? get('/api/service-usage') : Promise.resolve([]), can('datasource.query.read') ? get('/api/accessible-datasets') : Promise.resolve([])]); try { users.value = (await get('/api/organization')).users || [] } catch { users.value = [] } } catch (e) { error.value = e.message } }
async function createService() { try { error.value = ''; await post('/api/services', form.value); message.value = '服务草稿已创建'; serviceDialog.value = false; form.value = { name: '', datasetId: null, fields: [], limit: 100 }; await load() } catch (e) { error.value = e.message } }
async function action(path, text) { try { error.value = ''; await post(path); message.value = text; await load() } catch (e) { error.value = e.message } }
async function createCaller() { try { error.value = ''; const result = await post('/api/service-callers', caller.value); token.value = result.token; callerDialog.value = false; caller.value = { name:'', userId:null, limitPerMinute:60 }; await load() } catch (e) { error.value = e.message } }
async function createGrant() { if (!grant.value.service || !grant.value.caller) { error.value = '请选择服务和调用方'; return } try { error.value = ''; await post(`/api/services/${grant.value.service}/callers/${grant.value.caller}`); message.value = '调用方已授权'; grantDialog.value = false; await load() } catch (e) { error.value = e.message } }
onMounted(load)
</script>
<template><section><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-alert v-if="message" :title="message" type="success" :closable="false" show-icon/><el-alert title="调用方令牌仅创建时显示一次。请通过 HTTPS 和安全渠道传递；调用时使用 Authorization: Bearer 令牌。" type="info" :closable="false" show-icon/>
<el-tabs><el-tab-pane label="服务"><div class="toolbar list-query-toolbar"><div class="list-query-controls"><el-input v-model="serviceSearch" clearable placeholder="搜索服务名称或状态" @keyup.enter="applyServiceQuery"/><el-button type="primary" @click="applyServiceQuery">查询</el-button><span>已加载 {{ filteredServices.length }} 条服务</span></div><div class="list-query-actions"><el-button v-if="can('service.service.create') && can('datasource.query.read')" type="primary" @click="error = ''; serviceDialog = true">新增</el-button><el-button class="refresh-button" title="刷新" aria-label="刷新" @click="load"><RefreshIcon /></el-button></div></div><el-dialog v-model="serviceDialog" title="新建服务" width="min(640px, 95vw)"><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-form label-position="top" @submit.prevent="createService"><div class="grid"><el-form-item label="服务名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="授权数据集"><el-select v-model="form.datasetId" @change="form.fields = []"><el-option v-for="d in datasets" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-form-item label="输出字段"><el-select v-model="form.fields" multiple><el-option v-for="f in dataset?.fields || []" :key="f" :label="f" :value="f"/></el-select></el-form-item><el-form-item label="最多返回行数"><el-input-number v-model="form.limit" :min="1" :max="1000"/></el-form-item></div><el-button v-if="can('service.service.create') && can('datasource.query.read')" type="primary" native-type="submit">创建草稿</el-button></el-form></el-dialog><el-table :data="visibleServices"><el-table-column prop="name" label="服务"/><el-table-column label="状态"><template #default="scope"><el-tag :type="scope.row.state === 'PUBLISHED' ? 'success' : scope.row.state === 'PENDING' ? 'warning' : 'info'" effect="light">{{ scope.row.state }}</el-tag></template></el-table-column><el-table-column label="接口"><template #default="scope">GET /api/service-call/{{ scope.row.id }}</template></el-table-column><el-table-column label="操作" min-width="260"><template #default="scope"><el-button v-if="can('service.service.submit') && ['DRAFT','OFFLINE'].includes(scope.row.state)" text @click="action(`/api/services/${scope.row.id}/submit`, '已提交审批')">提交审批</el-button><el-button v-if="can('service.service.approve') && scope.row.state === 'PENDING'" text type="primary" @click="action(`/api/services/${scope.row.id}/approve`, '服务已发布')">审批并发布</el-button><el-popconfirm v-if="can('service.service.submit') && scope.row.state === 'PUBLISHED'" title="下线后调用方将无法访问，确定下线？" @confirm="action(`/api/services/${scope.row.id}/withdraw`, '服务已下线')"><template #reference><el-button text type="primary">下线</el-button></template></el-popconfirm></template></el-table-column></el-table><el-pagination v-model:current-page="servicePage" :page-size="10" :total="filteredServices.length" layout="total, prev, pager, next" /></el-tab-pane>
<el-tab-pane label="调用方"><div class="toolbar list-query-toolbar"><div class="list-query-controls"><el-input v-model="callerSearch" clearable placeholder="搜索调用方名称或用户编号" @keyup.enter="applyCallerQuery"/><el-button type="primary" @click="applyCallerQuery">查询</el-button><span>已加载 {{ filteredCallers.length }} 个调用方</span></div><div class="list-query-actions"><el-button v-if="can('service.caller.create')" type="primary" @click="error = ''; callerDialog = true">新增</el-button><el-button class="refresh-button" title="刷新" aria-label="刷新" @click="load"><RefreshIcon /></el-button></div></div><el-dialog v-model="callerDialog" title="新建调用方" width="min(640px, 95vw)"><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-form label-position="top" @submit.prevent="createCaller"><div class="grid"><el-form-item label="调用方名称"><el-input v-model="caller.name"/></el-form-item><el-form-item label="绑定用户（权限和部门来源）"><el-select v-if="users.length" v-model="caller.userId"><el-option v-for="u in users" :key="u.id" :label="u.username" :value="u.id"/></el-select><el-input-number v-else v-model="caller.userId" :min="1"/></el-form-item><el-form-item label="每分钟调用上限"><el-input-number v-model="caller.limitPerMinute" :min="1" :max="10000"/></el-form-item></div><el-button type="primary" native-type="submit">创建调用方</el-button></el-form></el-dialog><el-alert v-if="token" type="warning" :closable="true" @close="token = ''"><template #title>请立即安全保存令牌，关闭后无法再次查看</template><code class="token">{{ token }}</code></el-alert><el-table :data="visibleCallers"><el-table-column prop="name" label="调用方"/><el-table-column prop="userId" label="绑定用户编号"/><el-table-column prop="limitPerMinute" label="每分钟上限"/><el-table-column label="状态"><template #default="scope">{{ scope.row.enabled ? '启用' : '停用' }}</template></el-table-column><el-table-column label="操作"><template #default="scope"><el-popconfirm v-if="can('service.caller.disable') && scope.row.enabled" title="停用后令牌立即失效，确定停用？" @confirm="action(`/api/service-callers/${scope.row.id}/disable`, '调用方已停用')"><template #reference><el-button text type="primary">停用</el-button></template></el-popconfirm></template></el-table-column></el-table><el-pagination v-model:current-page="callerPage" :page-size="10" :total="filteredCallers.length" layout="total, prev, pager, next" /></el-tab-pane>
<el-tab-pane label="授权"><div class="toolbar list-query-toolbar"><div class="list-query-controls"><el-input v-model="grantSearch" clearable placeholder="搜索服务编号或调用方编号" @keyup.enter="applyGrantQuery"/><el-button type="primary" @click="applyGrantQuery">查询</el-button><span>已加载 {{ filteredGrants.length }} 条授权</span></div><div class="list-query-actions"><el-button v-if="can('service.caller.manage_grant') && can('service.service.read') && can('service.caller.read')" type="primary" @click="error = ''; grantDialog = true">新增</el-button><el-button class="refresh-button" title="刷新" aria-label="刷新" @click="load"><RefreshIcon /></el-button></div></div><el-dialog v-model="grantDialog" title="新增授权" width="min(580px, 95vw)"><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><div class="row"><el-select v-model="grant.service" placeholder="选择已发布服务"><el-option v-for="s in services.filter(x => x.state === 'PUBLISHED')" :key="s.id" :label="s.name" :value="s.id"/></el-select><el-select v-model="grant.caller" placeholder="选择启用的调用方"><el-option v-for="c in callers.filter(x => x.enabled)" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-button v-if="can('service.caller.manage_grant') && can('service.service.read') && can('service.caller.read')" type="primary" @click="createGrant">授权</el-button></div></el-dialog><el-table :data="visibleGrants"><el-table-column prop="serviceId" label="服务编号"/><el-table-column prop="callerId" label="调用方编号"/><el-table-column label="操作"><template #default="scope"><el-popconfirm v-if="can('service.caller.manage_grant') && can('service.caller.read')" title="撤销后该调用方无法访问此服务，确定撤销？" @confirm="action(`/api/services/${scope.row.serviceId}/callers/${scope.row.callerId}/revoke`, '授权已撤销')"><template #reference><el-button text type="primary">撤销</el-button></template></el-popconfirm></template></el-table-column></el-table><el-pagination v-model:current-page="grantPage" :page-size="10" :total="filteredGrants.length" layout="total, prev, pager, next" /></el-tab-pane>
<el-tab-pane label="调用统计"><div class="toolbar list-query-toolbar"><div class="list-query-controls"><el-input v-model="usageSearch" clearable placeholder="搜索服务编号或调用方编号" @keyup.enter="applyUsageQuery"/><el-button type="primary" @click="applyUsageQuery">查询</el-button><span>已加载 {{ filteredUsage.length }} 条统计</span></div><div class="list-query-actions"><el-button class="refresh-button" title="刷新" aria-label="刷新" @click="load"><RefreshIcon /></el-button></div></div><el-table :data="visibleUsage"><el-table-column prop="serviceId" label="服务编号"/><el-table-column prop="callerId" label="调用方编号"/><el-table-column prop="total" label="已接收"/><el-table-column prop="successful" label="成功"/><el-table-column prop="failed" label="失败"/></el-table><el-pagination v-model:current-page="usagePage" :page-size="10" :total="filteredUsage.length" layout="total, prev, pager, next" /><p>进行中或中断的请求包含在已接收总数中。</p></el-tab-pane></el-tabs></section></template>
<style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;margin:12px 0 18px;color:#637a75}.el-pagination{margin:18px 0;justify-content:flex-end}.pane{background:white;border:1px solid #e1eae8;padding:20px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px}.row{display:flex;gap:12px}.token{display:block;overflow-wrap:anywhere;user-select:all}@media(max-width:700px){.grid{grid-template-columns:1fr}.row{flex-wrap:wrap}}</style>
